**CachedPostsRepository.kt**:

```kotlin
class CachedPostsRepository(
    private val delegate: PostsRepository,
    private val feedCache: ResponseCache<PostsFeed>,
    private val postCache: ResponseCache<Post>,
) : PostsRepository {

    override suspend fun getPost(postId: String?): Result<Post> {
        if (postId != null) {
            postCache.get("post:$postId")?.let { return Result.Success(it) }
        }
        return delegate.getPost(postId).also { result ->
            if (result is Result.Success && postId != null) {
                postCache.put("post:$postId", result.data)
            }
        }
    }

    override suspend fun getPostsFeed(): Result<PostsFeed> {
        feedCache.get("posts:feed")?.let { return Result.Success(it) }
        return delegate.getPostsFeed().also { result ->
            if (result is Result.Success) {
                feedCache.put("posts:feed", result.data, ttlMillis = 30 * 60 * 1000)
            }
        }
    }

    override suspend fun toggleFavorite(postId: String) {
        delegate.toggleFavorite(postId)
        feedCache.remove("posts:feed") // Invalidate feed on user action
    }

    override fun observeFavorites(): Flow<Set<String>> = delegate.observeFavorites()
    override fun observePostsFeed(): Flow<PostsFeed?> = delegate.observePostsFeed()
}
```

